from __future__ import annotations

# Mapping from an event's `method` field to its channel name.
_METHOD_TO_CHANNEL: dict[str, str] = {
    "values": "values",
    "checkpoints": "checkpoints",
    "updates": "updates",
    "messages": "messages",
    "tools": "tools",
    "lifecycle": "lifecycle",
    "tasks": "tasks",
    "input.requested": "input",
}


def normalize_segment(segment: str) -> str:
    """Strip the suffix starting at the first colon from a segment.

    Returns the segment unchanged if it contains no colon.
    """
    index = segment.find(":")
    if index == -1:
        return segment
    return segment[:index]


def is_prefix_match(namespace: list[str], prefix: list[str]) -> bool:
    """Return True if `namespace` starts with all segments in `prefix`.

    Each namespace segment is normalized (colon-suffix stripped) before
    comparison. A prefix segment containing a colon is treated as an exact
    literal and compared against the raw (un-normalized) namespace segment.
    An empty prefix matches any namespace. Returns False if the prefix is
    longer than the namespace.
    """
    if len(prefix) > len(namespace):
        return False
    for ns_segment, prefix_segment in zip(namespace, prefix):
        if ":" in prefix_segment:
            if ns_segment != prefix_segment:
                return False
        elif normalize_segment(ns_segment) != prefix_segment:
            return False
    return True


def namespace_matches(
    namespace: list[str],
    prefixes: list[list[str]] | None,
    depth: int | None,
) -> bool:
    """Return True if `namespace` matches the given prefixes and depth.

    When `prefixes` is None or empty, any namespace matches. When `depth` is
    given, namespaces deeper than the limit do not match even if a prefix
    matches. Otherwise a namespace matches when at least one prefix passes
    `is_prefix_match`.
    """
    if not prefixes:
        return True
    if depth is not None and len(namespace) > depth:
        return False
    return any(is_prefix_match(namespace, prefix) for prefix in prefixes)


def infer_channel(event: dict) -> str | None:
    """Infer the channel name from an event's `method` field.

    Returns None for unknown methods. For the `custom` method, returns
    `custom:{name}` when the event data carries a non-empty `name` field, and
    `custom` otherwise.
    """
    method = event.get("method")
    if method == "custom":
        data = event.get("data")
        name = data.get("name") if isinstance(data, dict) else None
        if name:
            return f"custom:{name}"
        return "custom"
    if isinstance(method, str):
        return _METHOD_TO_CHANNEL.get(method)
    return None


def _channel_in(channel: str, channels: list[str]) -> bool:
    for entry in channels:
        if entry == channel:
            return True
        # A bare `custom` entry matches any namespaced custom channel.
        if entry == "custom" and channel.startswith("custom:"):
            return True
    return False


def matches_subscription(event: dict, subscription: dict) -> bool:
    """Return True if `event` matches `subscription`.

    The event's inferred channel must be listed in `subscription['channels']`
    (a bare `custom` entry matches any `custom:*` channel). When the
    subscription carries a `namespaces` filter, the event's namespace must also
    pass `namespace_matches`.
    """
    channel = infer_channel(event)
    if channel is None:
        return False
    channels = subscription.get("channels") or []
    if not _channel_in(channel, channels):
        return False
    namespace = event.get("namespace") or []
    return namespace_matches(
        namespace, subscription.get("namespaces"), subscription.get("depth")
    )
